package filearchive

import (
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"

	"filippo.io/age"
	"golang.org/x/sys/unix"
)

// Identity is a private native age X25519 recovery key.
type Identity struct {
	key *age.X25519Identity
}

// Recipient returns the public key accepted by the backup writer.
func (i *Identity) Recipient() string {
	return i.key.Recipient().String()
}

// LoadIdentity reads a dedicated private age X25519 identity file. It permits
// the comment lines generated by age-keygen.
func LoadIdentity(name string) (*Identity, error) {
	f, err := OpenLocal(name)
	if err != nil {
		return nil, errors.New("cannot open the private age identity file")
	}
	defer f.Close()
	const limit = 4096
	info, err := f.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm()&0077 != 0 || info.Size() > limit {
		return nil, errors.New("age identity must be a private regular file (mode 0600)")
	}
	raw, err := io.ReadAll(io.LimitReader(f, limit+1))
	if err != nil || len(raw) > limit {
		return nil, errors.New("cannot read the private age identity file")
	}
	var key *age.X25519Identity
	for line := range strings.SplitSeq(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if key != nil {
			return nil, errors.New("identity file must contain one native age X25519 secret key")
		}
		key, err = age.ParseX25519Identity(line)
		if err != nil {
			return nil, errors.New("identity file must contain one native age X25519 secret key")
		}
	}
	if key == nil {
		return nil, errors.New("identity file must contain one native age X25519 secret key")
	}
	return &Identity{key: key}, nil
}

// CreateIdentity exclusively creates a private key file and returns its
// public recipient. Existing files and symlinks are left untouched.
func CreateIdentity(name string) (string, error) {
	if name == "" {
		return "", errors.New("a new identity file path is required")
	}
	key, err := age.GenerateX25519Identity()
	if err != nil {
		return "", err
	}
	full, err := filepath.Abs(name)
	if err != nil {
		return "", err
	}
	parent, err := openDirectory(filepath.Dir(full))
	if err != nil {
		return "", err
	}
	defer parent.Close()
	parentFD := int(parent.Fd())
	base := filepath.Base(full)
	fd, err := unix.Openat(parentFD, base, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC, 0600)
	if err != nil {
		return "", err
	}
	f := os.NewFile(uintptr(fd), name)
	_, writeErr := io.WriteString(f, key.String()+"\n")
	modeErr := f.Chmod(0600)
	syncErr := f.Sync()
	closeErr := f.Close()
	if err := errors.Join(writeErr, modeErr, syncErr, closeErr, parent.Sync()); err != nil {
		_ = unix.Unlinkat(parentFD, base, 0)
		return "", err
	}
	return key.Recipient().String(), nil
}
